style.css:
@-moz-document domain("pinterest.com") {
[data-test-id="pin"] {
        background: #fffdf8 !important;
        padding: 8px 8px 32px 8px !important;
        border-radius: 2px !important;
        box-shadow: 0 5px 15px rgba(55, 35, 20, 0.2) !important;
    }

    [data-test-id="pin"] img {
        border-radius: 1px !important;
    }

    [data-test-id="pin"]:hover {
        transform: rotate(-1deg) translateY(-3px) !important;
        transition: transform 0.25s ease !important;
    }
}
